do $$ declare s uuid:=gen_random_uuid();u uuid:=gen_random_uuid();v uuid:=gen_random_uuid();c uuid:=gen_random_uuid();d uuid:=gen_random_uuid();policy uuid:=gen_random_uuid();warehouse uuid;version integer;profile integer;collection uuid:=gen_random_uuid();result jsonb;
begin
 insert into public.stores values(s);insert into public.memberships values(s,u,'owner');insert into public.store_billing values(s,'sandbox','premium','ACTIVE',now()-interval '1 day',now()+interval '1 month');insert into public.policy_versions(id,store_id) values(policy,s);
 insert into public.eligibility_decisions(id,store_id,policy_version_id,outcome,order_id) values(d,s,policy,'ELIGIBLE','100');insert into public.return_cases(id,store_id,status,decision_id,order_id,item_snapshot) values(c,s,'OPEN',d,'100','{"sku":"SHOE-1","quantity":1}');insert into public.whatsapp_conversations(id,store_id,return_case_id) values(v,s,c);
 warehouse:=public.shipping_register_warehouse(s,'sandbox','AUTO-'||s::text);version:=public.shipping_settings_save(s,u,0,warehouse,array['2828'],'PICKUP_BY_DC',10000,true);version:=public.shipping_settings_approve(s,u,version,repeat('f',64));
 perform public.shipping_apply_verified_topup(s,'sandbox','auto-test-'||s::text,15000);
 perform public.shipping_collection_confirm(s,v,c,collection,version,'v1.YQ==.Yg==');
 perform public.test_shipping_assert(not has_function_privilege('authenticated','public.shipping_automation_claim(uuid,uuid,uuid,integer,integer,text,integer,text,uuid)','execute'),'browser cannot claim');
 perform public.test_shipping_assert(not has_table_privilege('service_role','private.shipping_parcels','select'),'raw profiles not API exposed');
 perform public.test_shipping_reject(format('select public.shipping_parcel_save(%L,%L,''SHOE-1'',1,0,1000,300,200,120,false)',s,u));
 profile:=public.shipping_parcel_save(s,u,'SHOE-1',1,0,1000,300,200,120,true);
 perform public.test_shipping_assert(profile=1,'first profile version');
 perform public.test_shipping_reject(format('select public.shipping_parcel_save(%L,%L,''SHOE-1'',1,0,1000,300,200,120,true)',s,u));
 perform public.test_shipping_reject(format('select public.shipping_automation_claim(%L,%L,%L,%s,0,''2828'',6842,%L,%L)',s,v,c,version,repeat('f',64),d));
 perform public.test_shipping_reject(format('select public.shipping_automation_claim(%L,%L,%L,%s,1,''2828'',10001,%L,%L)',s,v,c,version,repeat('f',64),d));
 update public.store_billing set plan='standard' where store_id=s;
 perform public.test_shipping_reject(format('select public.shipping_automation_claim(%L,%L,%L,%s,1,''2828'',6842,%L,%L)',s,v,c,version,repeat('f',64),d));update public.store_billing set plan='premium' where store_id=s;
 perform public.test_shipping_assert(public.shipping_automation_claim(s,v,c,version,1,'2828',6842,repeat('f',64),d),'single claim');
 perform public.test_shipping_assert(not public.shipping_automation_claim(s,v,c,version,1,'2828',6842,repeat('f',64),d),'no replay');
 perform public.test_shipping_assert((select available_halalas=5000 and reserved_halalas=10000 from private.shipping_wallets where store_id=s),'reserve approved maximum once');
 perform public.test_shipping_assert((select count(*) from private.shipping_ledger where store_id=s and kind='RESERVE')=1,'one reserve entry');
 perform public.shipping_automation_issue(s,v,c,'ABOVE_CAP');perform public.shipping_automation_issue(s,v,c,'ABOVE_CAP');
 perform public.test_shipping_assert((select count(*) from private.shipping_automation_issues where store_id=s)=1,'deduped improvement signals');
 perform public.shipping_automation_advance(s,v,c,'ORDER_CREATING','ORDER_READY');perform public.shipping_automation_advance(s,v,c,'ORDER_READY','RETURN_CREATING');perform public.shipping_automation_advance(s,v,c,'RETURN_CREATING','RETURN_REQUESTED');
 perform public.test_shipping_reject(format('select public.shipping_automation_advance(%L,%L,%L,''RETURN_REQUESTED'',''ORDER_CREATING'')',s,v,c));
 result:=public.shipping_automation_read(s,v,c);perform public.test_shipping_assert(result->'booking'->>'stage'='RETURN_REQUESTED','safe read existing stage');
 profile:=public.shipping_parcel_save(s,u,'SHOE-1',1,1,1200,310,210,130,true);
 perform public.test_shipping_assert((select parcel_snapshot->>'weight_grams' from private.shipping_automation where store_id=s)='1000','submitted parcel snapshot frozen');
 perform public.test_shipping_reject(format('select public.shipping_automation_read(%L,%L,%L)',gen_random_uuid(),v,c));
end $$;
